/* Safe Chess service worker (generated by scripts/build-sw.mjs from this template).
 *
 * Keeps a copy of the whole static app so the robot modes work offline.
 * It only handles this app's own files: requests to any other host (such as
 * the friend-mode server later) are never touched or stored. */

const VERSION = "__VERSION__";
const CACHE = `safe-chess-${VERSION}`;
/** Every file of the static build. */
const FILES = __FILES__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(FILES))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((k) => k.startsWith("safe-chess-") && k !== CACHE).map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(respond(request, url));
});

/** "/" → "/index.html", "/robot" → "/robot.html" (how the static pages are named). */
function pageFile(pathname) {
  if (pathname.endsWith("/")) return `${pathname}index.html`;
  if (!/\.[a-z0-9]+$/i.test(pathname)) return `${pathname}.html`;
  return pathname;
}

async function respond(request, url) {
  const cache = await caches.open(CACHE);
  const options = { ignoreSearch: true, ignoreVary: true };
  const key = request.mode === "navigate" ? pageFile(url.pathname) : request;
  const cached = await cache.match(key, options);
  if (cached) {
    // A stored response remembers its address without the "#…" part, and a
    // worker takes its address from the response. The robot's engine worker
    // reads its start-up settings from "#…", so hand it a fresh response,
    // which keeps the full address it was requested with.
    if (request.destination === "worker") {
      return new Response(cached.body, {
        status: cached.status,
        statusText: cached.statusText,
        headers: cached.headers,
      });
    }
    return cached;
  }
  try {
    return await fetch(request);
  } catch (error) {
    if (request.mode === "navigate") {
      const notFound = await cache.match("/404.html");
      if (notFound) return notFound;
    }
    throw error;
  }
}
